import { useCallback, useEffect, useMemo } from 'react';

import {
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  useSubFilters,
} from 'hooks';
import type { Option } from 'models/Filters';

import {
  buildPostAppliedForDrill,
  getAvailableWaterfallOptions,
  getNextWaterfallFilterAfterDrill,
  getSubBrands,
  hasSingleSubBrand,
  resolveWaterfallFilterOnContextChange,
  WATERFALL_VIEW_HIERARCHY,
} from '../../utils/resolveCommercialResultsWaterfallOptions';

interface UseCommercialResultsWaterfallFilterSyncParams {
  contextKey: string;
  rawOptions: Option[];
}

export const CR_WATERFALL_RESET_EVENT = 'cr-waterfall:filter-reset';
export const useCommercialResultsWaterfallFilterSync = ({
  contextKey,
  rawOptions,
}: UseCommercialResultsWaterfallFilterSyncParams) => {
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const { activeSubFilters, setSubFilterValue } = useSubFilters();
  const { updateForm, apply } = usePageFilterManagement(currentPage);
  const availableOptions = useMemo(
    () => getAvailableWaterfallOptions(applied, dataFilters, rawOptions),
    [applied, dataFilters, rawOptions],
  );
  const currentWaterfallFilter = activeSubFilters?.waterfall_filter as
    | string
    | undefined;

  const handleWaterfallFilterChange = useCallback(
    (value: string) => {
      setSubFilterValue('waterfall_filter', value);
    },
    [setSubFilterValue],
  );

  const syncWaterfallFilterAfterDrill = useCallback(
    (
      currentView: string,
      clickedLabel: string | string[],
      nextRawOptions: Option[] = rawOptions,
    ) => {
      const postApplied = buildPostAppliedForDrill(
        applied,
        currentView,
        clickedLabel,
      );
      const nextFilter = getNextWaterfallFilterAfterDrill(
        currentView,
        postApplied,
        dataFilters,
        nextRawOptions,
        applied,
      );

      if (nextFilter) {
        setSubFilterValue('waterfall_filter', nextFilter);
      }
    },
    [applied, dataFilters, rawOptions, setSubFilterValue],
  );

  const resolveValueOnContextChange = useCallback(
    (currentValue: string) =>
      resolveWaterfallFilterOnContextChange({
        currentValue,
        availableOptions,
      }),
    [availableOptions],
  );
  useEffect(() => {
    const handleFilterReset = () => {
      const firstOfHierarchy = WATERFALL_VIEW_HIERARCHY[0];

      if (firstOfHierarchy && firstOfHierarchy !== currentWaterfallFilter) {
        setSubFilterValue('waterfall_filter', firstOfHierarchy);
      }
    };
    globalThis.addEventListener(CR_WATERFALL_RESET_EVENT, handleFilterReset);
    return () =>
      globalThis.removeEventListener(
        CR_WATERFALL_RESET_EVENT,
        handleFilterReset,
      );
  }, [currentWaterfallFilter, setSubFilterValue]);

  useEffect(() => {
    if (!availableOptions.length || !currentWaterfallFilter) {
      return;
    }

    const isCurrentValid = availableOptions.some(
      (option) => option.value === currentWaterfallFilter,
    );

    if (!isCurrentValid) {
      const nextValue = resolveWaterfallFilterOnContextChange({
        currentValue: currentWaterfallFilter,
        availableOptions,
      });
      if (nextValue && nextValue !== currentWaterfallFilter) {
        setSubFilterValue('waterfall_filter', nextValue);
        if (
          ['sku', 'pack_type'].includes(nextValue) &&
          hasSingleSubBrand(dataFilters, applied?.brands)
        ) {
          const nextSubBrand = getSubBrands(dataFilters)[0]?.value ?? 'All';

          if (applied?.sub_brands !== nextSubBrand) {
            updateForm('sub_brands', nextSubBrand);
            apply();
          }
        }
      }
    }
  }, [
    applied,
    availableOptions,
    contextKey,
    currentWaterfallFilter,
    setSubFilterValue,
    dataFilters,
    updateForm,
    apply,
  ]);

  return {
    handleWaterfallFilterChange,
    syncWaterfallFilterAfterDrill,
    resolveValueOnContextChange,
    availableOptions,
  };
};
